  @protected
  void sse_encode_api_error(ApiError self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case ApiError_NotLoggedIn():
        sse_encode_i_32(0, serializer);
      case ApiError_NoPlayableUrl():
        sse_encode_i_32(1, serializer);
      case ApiError_UnsupportedFormat():
        sse_encode_i_32(2, serializer);
      case ApiError_UnverifiedFormat():
        sse_encode_i_32(3, serializer);
      case ApiError_LoginFailed(detail: final detail):
        sse_encode_i_32(4, serializer);
        sse_encode_String(detail, serializer);
      case ApiError_InvalidCookie(missing: final missing):
        sse_encode_i_32(5, serializer);
        sse_encode_String(missing, serializer);
      case ApiError_ServerError(api: final api, code: final code):
        sse_encode_i_32(6, serializer);
        sse_encode_String(api, serializer);
        sse_encode_String(code, serializer);
      case ApiError_BadResponse(detail: final detail):
        sse_encode_i_32(7, serializer);
        sse_encode_String(detail, serializer);
      case ApiError_Network(detail: final detail):
        sse_encode_i_32(8, serializer);
        sse_encode_String(detail, serializer);
      case ApiError_Internal(detail: final detail):
        sse_encode_i_32(9, serializer);
        sse_encode_String(detail, serializer);
    }
  }

